// @whimtex-effect Learn/Final Tint
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @param color _Tint = #FFFFFF
// @param float _Brightness = 1 [0 .. ~3]


float LearnHash(float2 p){ return frac(sin(dot(p,float2(127.1,311.7)))*43758.5453); }
float LearnNoise(float2 p, float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float LearnFbm(float2 p,float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 s.fractal_type=FNL_FRACTAL_FBM;s.octaves=3;s.gain=.42;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float2 LearnRotate(float2 p,float angle){float c=cos(radians(angle)),s=sin(radians(angle));return float2(c*p.x-s*p.y,s*p.x+c*p.y);}
float LearnEdge(float d,float softness){float w=max(fwidth(d),max(softness,.00001));return 1-smoothstep(-w,w,d);}
float LearnGauss(float x){return exp(-x*x);}

float4 ApplyFX(float2 uv,float4 color){

return float4(color.rgb*_Tint.rgb*_Brightness,color.a*_Tint.a*_Opacity);
}

// @whimtex-effect Learn/Radial Front
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @group(Placement)
// @param point _Center = (0.5, 0.5)
// @param float2 _Scale = (1, 1)
// @param float _Angle = 0 [-180 .. 180]
// @endgroup
// @group(Profile; _Style)
// @param hidden enum _Style = Mist {Mist:0, Fractured:1, Inward:2, Scalloped:3, Thin:4, Burst:5}
// @param float _Radius = 0.34 [0.05 .. 0.48]
// @param float _Width = 0.045 [0.001 .. 0.25]
// @param float _Softness = 0.02 [0 .. 0.15]
// @param float _Spikes = 0.1 [0 .. 0.3]
// @param float _Count = 12 [2 .. 64]
// @param float _Breakup = 0 [0 .. 1]
// @endgroup
// @group(Turbulence; _Seed)
// @param hidden float _Seed = 47 [1 .. ~5000]
// @param float _Frequency = 9 [1 .. 40]
// @param float _Warp = 0.03 [0 .. 0.15]
// @param float _Detail = 0.5 [0 .. 1]
// @endgroup

float LearnHash(float2 p){ return frac(sin(dot(p,float2(127.1,311.7)))*43758.5453); }
float LearnNoise(float2 p, float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float LearnFbm(float2 p,float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 s.fractal_type=FNL_FRACTAL_FBM;s.octaves=3;s.gain=.42;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float2 LearnRotate(float2 p,float angle){float c=cos(radians(angle)),s=sin(radians(angle));return float2(c*p.x-s*p.y,s*p.x+c*p.y);}
float LearnEdge(float d,float softness){float w=max(fwidth(d),max(softness,.00001));return 1-smoothstep(-w,w,d);}
float LearnGauss(float x){return exp(-x*x);}

float4 ApplyFX(float2 uv,float4 color){
float2 p=LearnRotate(LayerToLocal(uv)-_Center,-_Angle)/max(abs(_Scale),.001);

float r=length(p),a=atan2(p.y,p.x);float2 dir=p/max(r,.00001);
float n=LearnFbm(dir*_Frequency+float2(r*3,0),_Seed);
float broad=LearnNoise(dir*3,_Seed+37);
float spoke=pow(saturate(.5+.5*cos(a*round(_Count)+1.7*sin(a*3))),5);
spoke*=.35+.85*LearnNoise(dir*4,_Seed+81);
float radius=_Radius+(broad-.5)*_Warp;
float coverage=0;
if(_Style<.5){
 float d=r-radius-(n-.5)*_Warp*.5;
 coverage=LearnGauss(d/max(_Width+_Softness*.3,.001))*lerp(1,saturate(.15+n*1.6),_Detail);
 coverage*=1-_Breakup*smoothstep(.5,.75,broad);
}else if(_Style<1.5){
 float outer=radius+_Spikes*spoke;
 float inner=radius-_Width+_Spikes*.2*LearnNoise(dir*2,_Seed+13);
 coverage=LearnEdge(r-outer,_Softness)*(1-LearnEdge(r-inner,_Softness));
 coverage*=LearnEdge(_Breakup-broad,.02);
}else if(_Style<2.5){
 float depth=max(0,radius-r);float reach=_Width+_Spikes*pow(saturate(broad*1.1),2);
 coverage=LearnEdge(r-radius,_Softness)*exp(-depth/max(reach,.002));
 coverage*=smoothstep(radius*.17,radius*.55,r);
}else if(_Style<3.5){
 float q=.5+.5*sin(a*round(_Count));
 float inner=radius-_Width-_Spikes*pow(q,10);
 coverage=LearnEdge(r-radius,_Softness)*(1-LearnEdge(r-inner,_Softness));
}else if(_Style<4.5){
 coverage=LearnEdge(r-radius,_Softness)*exp(-max(0,radius-r)/max(_Width,.001));
}else{
 float outer=radius+_Spikes*spoke+(broad-.5)*_Warp;
 coverage=LearnEdge(r-outer,_Softness)*pow(saturate(1-r/max(outer,.001)),.7);
}
return float4(1,1,1,saturate(coverage)*_Opacity);
}
